using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query.Execution;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Integration;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.CrossDomain;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Graph;using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationRegistrationTests{[Fact]public void Registers_complete_foundation_idempotently(){var s=new ServiceCollection();s.AddAstronomyKnowledgeFoundation();s.AddAstronomyKnowledgeFoundation();Assert.Throws<ArgumentNullException>(()=>AstronomyKnowledgeFoundationRegistrationExtensions.AddAstronomyKnowledgeFoundation(null!));Assert.Single(s.Where(d=>d.ServiceType==typeof(IAstronomyKnowledgeFoundationCapabilities)));Assert.Single(s.Where(d=>d.ServiceType==typeof(IAstronomyKnowledgeFoundationCompatibilityVerifier)));using var p=s.BuildServiceProvider();Assert.IsType<AstronomyKnowledgeCatalog>(p.GetRequiredService<IAstronomyKnowledgeCatalog>());Assert.Same(p.GetRequiredService<IAstronomyKnowledgeCatalog>(),p.GetRequiredService<IAstronomyKnowledgeCatalog>());Assert.IsAssignableFrom<IAstronomyTypedPayloadRegistry>(p.GetRequiredService<IAstronomyTypedPayloadRegistry>());Assert.IsAssignableFrom<IAstronomyKnowledgeValidationRuleRegistry>(p.GetRequiredService<IAstronomyKnowledgeValidationRuleRegistry>());Assert.IsAssignableFrom<IAstronomyCrossDomainValidationRuleRegistry>(p.GetRequiredService<IAstronomyCrossDomainValidationRuleRegistry>());Assert.IsAssignableFrom<IAstronomyKnowledgeGraphValidationRuleRegistry>(p.GetRequiredService<IAstronomyKnowledgeGraphValidationRuleRegistry>());Assert.IsType<AstronomyKnowledgeQueryValidator>(p.GetRequiredService<IAstronomyKnowledgeQueryValidator>());Assert.IsType<AstronomyKnowledgeCatalogQueryEngine>(p.GetRequiredService<IAstronomyKnowledgeCatalogQueryEngine>());Assert.IsType<AstronomyKnowledgeStatementQueryEngine>(p.GetRequiredService<IAstronomyKnowledgeStatementQueryEngine>());var ids=p.GetRequiredService<IAstronomyKnowledgeFoundationCapabilities>().Snapshot.Capabilities.Select(c=>c.Id).ToArray();Assert.Equal(ids.Length,ids.Distinct().Count());Assert.Empty(s.Where(d=>d.ServiceType.Name.Contains("DbContext",StringComparison.Ordinal)||d.ServiceType.Name.Contains("Repository",StringComparison.Ordinal)));}}
